type Step = Message => Either[StepError, Message]

def advance(msg: Message, slip: List[Step]): Either[StepError, Message] =
  slip.foldLeft[Either[StepError, Message]](Right(msg)) { (acc, step) =>
    acc.flatMap(step)   // first Left stops the slip, keeping the failed step visible
  }

